const std = @import("std"); const mem2 = std.mem; const pgzz = @import("nt-brow-page.zig");
const CF = .{ .napz = 400, .calm = 3, .more = 40 };
pub const Step = struct { op: []const u8, url: []const u8 = "", sele: []const u8 = "", text: []const u8 = "", ms: u32 = 0 };
pub const Acts = struct { scrl: u32 = 0, clic: []const u8 = "", cons: bool = false, ste2: []const Step = &.{}, pub fn any(self: Acts) bool { return self.scrl > 0 or self.clic.len > 0 or self.cons or self.ste2.len > 0; } };
pub fn stepRead(aren: std.mem.Allocator, text: []const u8, maxz: u32) ![]const Step { const lstz = std.json.parseFromSliceLeaky([]const Step, aren, text, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadSteps; if (lstz.len > maxz) return error.StepLimit; for (lstz) |stpz| { const oka2 = mem2.eql(u8, stpz.op, "goto") or mem2.eql(u8, stpz.op, "click") or mem2.eql(u8, stpz.op, "clicktext") or mem2.eql(u8, stpz.op, "type") or mem2.eql(u8, stpz.op, "wait") or mem2.eql(u8, stpz.op, "waitsel") or mem2.eql(u8, stpz.op, "scroll") or mem2.eql(u8, stpz.op, "extract"); if (!oka2) return error.BadSteps; } return lstz; }
pub fn scroll(self: *pgzz.Page, aren: std.mem.Allocator, maxz: u32) u32 { var con2: u32 = 0; var same: u32 = 0; var last: i64 = -1; while (con2 < maxz and self.left() > 0) : (con2 += 1) { _ = self.evalNumb(aren, "window.scrollTo(0,document.documentElement.scrollHeight),1"); self.napz(CF.napz); const hgtz = self.evalNumb(aren, "document.documentElement.scrollHeight"); if (hgtz == last) { same += 1; if (same >= CF.calm) break; } else same = 0; last = hgtz; } return con2; }
pub fn clicSelz(self: *pgzz.Page, aren: std.mem.Allocator, sele: []const u8) !bool { const qryz = try std.json.Stringify.valueAlloc(aren, sele, .{}); const expr = try std.fmt.allocPrint(aren, "(function(s){{var e=document.querySelector(s);if(!e)return 0;e.scrollIntoView();e.click();return 1}})({s})", .{qryz}); return self.evalNumb(aren, expr) == 1; }
pub fn clicText(self: *pgzz.Page, aren: std.mem.Allocator, text: []const u8) !bool { const qryz = try std.json.Stringify.valueAlloc(aren, text, .{}); const expr = try std.fmt.allocPrint(aren, "(function(t){{t=t.toLowerCase();var l=document.querySelectorAll('button,a,[role=button],input[type=button],input[type=submit]');for(var i=0;i<l.length;i++){{var x=(l[i].innerText||l[i].value||'').trim().toLowerCase();if(x.indexOf(t)>=0){{l[i].scrollIntoView();l[i].click();return 1}}}}return 0}})({s})", .{qryz}); return self.evalNumb(aren, expr) == 1; }
pub fn loadMore(self: *pgzz.Page, aren: std.mem.Allocator, text: []const u8, maxz: u32) !u32 { var con2: u32 = 0; while (con2 < @min(maxz, CF.more) and self.left() > 0) : (con2 += 1) { const before = self.evalNumb(aren, "document.body.innerText.length"); if (!try clicText(self, aren, text)) break; self.napz(CF.napz); self.settle(aren); if (self.evalNumb(aren, "document.body.innerText.length") <= before) { con2 += 1; break; } } return con2; }
pub fn consent(self: *pgzz.Page, aren: std.mem.Allocator, sels: []const []const u8) !u32 { var con2: u32 = 0; for (sels) |selz| { if (try clicSelz(self, aren, selz)) { con2 += 1; self.napz(CF.napz); } } if (con2 > 0) self.settle(aren); return con2; }
fn typeInzz(self: *pgzz.Page, aren: std.mem.Allocator, sele: []const u8, text: []const u8) !void { const qszz = try std.json.Stringify.valueAlloc(aren, sele, .{}); const qtzz = try std.json.Stringify.valueAlloc(aren, text, .{}); const expr = try std.fmt.allocPrint(aren, "(function(s,t){{var e=document.querySelector(s);if(!e)return 0;var ty=(e.getAttribute('type')||'').toLowerCase();var ac=(e.getAttribute('autocomplete')||'').toLowerCase();if(ty==='password'||ac.indexOf('password')>=0||ac.indexOf('one-time')>=0)return -1;e.focus();e.value=t;e.dispatchEvent(new Event('input',{{bubbles:true}}));e.dispatchEvent(new Event('change',{{bubbles:true}}));return 1}})({s},{s})", .{ qszz, qtzz }); const rslt = self.evalNumb(aren, expr); if (rslt == -1) return error.SecretField; if (rslt != 1) return error.NoElement; }
pub fn run(self: *pgzz.Page, aren: std.mem.Allocator, acts: Acts, sels: []const []const u8, scrm: u32, outp: *std.ArrayList(u8)) !void { if (acts.cons) _ = try consent(self, aren, sels); if (acts.clic.len > 0) _ = try loadMore(self, aren, acts.clic, scrm); if (acts.scrl > 0) _ = scroll(self, aren, @min(acts.scrl, scrm)); for (acts.ste2) |stpz| { if (self.left() == 0) return error.TimeUp; if (mem2.eql(u8, stpz.op, "goto")) { try self.navigate(aren, stpz.url, .{ .time_mill = self.left() }); } else if (mem2.eql(u8, stpz.op, "click")) { if (!try clicSelz(self, aren, stpz.sele)) return error.NoElement; self.napz(CF.napz); self.settle(aren); } else if (mem2.eql(u8, stpz.op, "clicktext")) { if (!try clicText(self, aren, stpz.text)) return error.NoElement; self.napz(CF.napz); self.settle(aren); } else if (mem2.eql(u8, stpz.op, "type")) { try typeInzz(self, aren, stpz.sele, stpz.text); } else if (mem2.eql(u8, stpz.op, "wait")) { self.napz(@min(stpz.ms, 30000)); } else if (mem2.eql(u8, stpz.op, "waitsel")) { const qryz = try std.json.Stringify.valueAlloc(aren, stpz.sele, .{}); const expr = try std.fmt.allocPrint(aren, "document.querySelector({s})!==null", .{qryz}); var okay = false; while (self.left() > 0) { if (self.evalNumb(aren, expr) == 1) { okay = true; break; } self.napz(250); } if (!okay) return error.TimeUp; } else if (mem2.eql(u8, stpz.op, "scroll")) { _ = scroll(self, aren, scrm); } else if (mem2.eql(u8, stpz.op, "extract")) { const qryz = try std.json.Stringify.valueAlloc(aren, stpz.sele, .{}); const expr = try std.fmt.allocPrint(aren, "Array.from(document.querySelectorAll({s})).map(function(e){{return e.innerText}}).join('\\n')", .{qryz}); const tex2 = try self.evalStrz(aren, expr); var itrz = mem2.splitScalar(u8, tex2, '\n'); while (itrz.next()) |lnzz| { if (lnzz.len == 0) continue; try outp.print(aren, "<div data-scra-extract=\"{s}\">", .{"x"}); for (lnzz) |chr2| switch (chr2) { '<' => try outp.appendSlice(aren, "&lt;"), '>' => try outp.appendSlice(aren, "&gt;"), '&' => try outp.appendSlice(aren, "&amp;"), else => try outp.append(aren, chr2) }; try outp.appendSlice(aren, "</div>"); } } } }
